{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6f1ec;--accent:#8a5a3b;--accent-2:#c79a74;--muted:#6b6b6b;--card:#fff;--glass:rgba(255,255,255,0.6);font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#efe8dd);color:#2f2f2f}
    .wrap{max-width:1000px;margin:28px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{background:var(--card);border-radius:14px;padding:22px;margin-top:18px;box-shadow:0 6px 20px rgba(46,36,29,0.06)}
    .hero h1{margin:0;font-size:22px;color:var(--accent)}
    .hero p{color:var(--muted);margin-top:6px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:18px}
    .plans{display:grid;gap:14px}
    .plan{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .plan h3{margin:0;color:#2b2b2b}
    .price{font-size:22px;color:var(--accent);margin-top:8px}
    .list{color:var(--muted);margin-top:10px}
    .cta-row{display:flex;gap:10px;margin-top:12px}
    .btn{padding:10px 14px;border-radius:10px;border:none;cursor:pointer;font-weight:700}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-outline{background:transparent;border:2px solid var(--accent-2);color:var(--accent)}
    aside .card{background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.5));padding:16px;border-radius:12px}
    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:28px;color:var(--muted);font-size:13px;text-align:center}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(12,8,6,0.5);display:none;align-items:center;justify-content:center}
    .modal{background:var(--card);padding:20px;border-radius:12px;max-width:720px;width:92%;box-shadow:0 10px 40px rgba(0,0,0,0.2)}
    .modal h2{margin:0 0 8px}
    .exercise-controls{display:flex;gap:10px;margin-top:12px}
    .timer{font-size:28px;font-weight:700;color:var(--accent)}
    .print-only{display:none}
    @media print{body *:not(.printable){display:none} .printable{display:block} .print-only{display:block}}
    /* small helper visuals */
    .pattern{width:100%;height:60px;margin-top:18px;border-radius:10px;overflow:hidden}
    .svg-pattern{width:100%;height:100%;display:block}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo">W</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Start</a>
        <a href="programs.html">Offerings</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Plan</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <h1>Smart investments in steadier days</h1>
      <p>Short, focused pathways and clear commitments to help you form reliable habits and measurable shifts. Choose what fits your rhythm.</p>
      <div style="margin-top:12px">
        <button class="btn btn-primary" onclick="location.href='book.html'">{{PRIMARY_CTA_LABEL}}</button>
        <button class="btn btn-outline" id="try-now-pricing">Try a short exercise</button>
      </div>
    </section>

    <div class="grid">
      <main>
        <div class="plans">
          <div class="plan">
            <h3>Solo Alignment — One Session</h3>
            <div class="price">$155 • single meeting</div>
            <div class="list">A focused conversation, a clear set of experiments and the habit list you'll try for 7 days.</div>
            <div class="cta-row">
              <button class="btn btn-primary" onclick="location.href='book.html#solo'">Book this</button>
              <button class="btn btn-outline" onclick="generateChallenge('Solo Alignment')">Make a 7-day plan</button>
            </div>
          </div>

          <div class="plan">
            <h3>Guided Cycle — Three Sessions</h3>
            <div class="price">$420 • 6–8 weeks</div>
            <div class="list">A short, structured series to introduce new rhythms and check progress with tailored practices.</div>
            <div class="cta-row">
              <button class="btn btn-primary" onclick="location.href='book.html#cycle'">Reserve a place</button>
              <button class="btn btn-outline" onclick="generateChallenge('Guided Cycle')">Create challenge</button>
            </div>
          </div>

          <div class="plan">
            <h3>Foundations — Monthly Support</h3>
            <div class="price">$1100 / month</div>
            <div class="list">Ongoing check-ins, habit adjustments, and a library of short practices designed around your priorities.</div>
            <div class="cta-row">
              <button class="btn btn-primary" onclick="location.href='contact.html'">Inquire</button>
              <button class="btn btn-outline" onclick="generateChallenge('Foundations')">Draft a month of routines</button>
            </div>
          </div>
        </div>

        <section style="margin-top:18px;background:linear-gradient(180deg,#fff,rgba(255,250,246,0.9));padding:12px;border-radius:12px">
          <h3 style="margin:0;color:var(--accent)">Why this structure?</h3>
          <p style="color:var(--muted);margin-top:8px">Pricing maps to the intensity of support and the length of habit practice. Each offering emphasizes small, repeatable actions, reflection prompts and a short set of reliable checks.</p>
        </section>
      </main>

      <aside>
        <div class="card">
          <h4 style="margin:0;color:var(--accent)">Make a 7-day start</h4>
          <p class="small">Generate a printable checklist tuned to one focus area. Use it as a scaffold for your first week.</p>
          <div style="margin-top:10px;display:flex;gap:8px">
            <select id="focus-select" style="flex:1;padding:8px;border-radius:8px;border:1px solid #eee">
              <option>Sleep rhythm</option>
              <option>Morning clarity</option>
              <option>Stress ease</option>
              <option>Movement habit</option>
              <option>Mindful pause</option>
            </select>
            <button class="btn btn-primary" onclick="generateChallenge()">Generate</button>
          </div>
          <div style="margin-top:12px;font-size:13px;color:var(--muted)">Need help deciding? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
        </div>

        <div style="margin-top:14px;" class="card">
          <h4 style="margin:0">Quick reassurance</h4>
          <p class="small">Refunds considered within first session for packaged offerings. Policies shared when you book.</p>
          <div style="margin-top:10px"><button class="btn btn-outline" onclick="location.href='faq.html'">Read policies</button></div>
        </div>
      </aside>
    </div>

    <div class="pattern" aria-hidden>
      <svg class="svg-pattern" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 60" preserveAspectRatio="none">
        <defs>
          <linearGradient id="g1" x1="0" x2="1">
            <stop offset="0" stop-color="#f3d6c0"/>
            <stop offset="1" stop-color="#f7eee6"/>
          </linearGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#g1)" />
        <g fill="none" stroke="#e9d2c0" stroke-width="1">
          <path d="M10 40 C 80 10, 120 50, 190 20 S 320 30, 390 5" opacity="0.6"/>
          <path d="M30 50 C 100 20, 160 60, 230 30 S 360 40, 430 15" opacity="0.35"/>
        </g>
      </svg>
    </div>

    <footer>
      <div>Questions? Call <strong>{{PHONE}}</strong> or <a href="mailto:{{EMAIL}}">email</a>.</div>
      <div style="margin-top:6px">© <span id="year"></span> {{BUSINESS_NAME}}</div>
    </footer>
  </div>

  <!-- Modal for guided exercise -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-hidden="true">
    <div class="modal" role="document" aria-labelledby="modal-title">
      <h2 id="modal-title">Try a 5-minute practice</h2>
      <p class="small">Choose a short guide: breathing, journaling prompt, or intention setting.</p>
      <div style="display:flex;gap:10px;margin-top:12px">
        <button class="btn btn-outline" onclick="startExercise('breath')">Breathing</button>
        <button class="btn btn-outline" onclick="startExercise('journal')">Journaling</button>
        <button class="btn btn-outline" onclick="startExercise('intention')">Intention</button>
        <div style="margin-left:auto">
          <button class="btn" onclick="closeModal()">Close</button>
        </div>
      </div>
      <div id="exercise-area" style="margin-top:16px"></div>
    </div>
  </div>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();
    // Modal controls
    document.getElementById('try-now-pricing').addEventListener('click', ()=>openModal());
    function openModal(){document.getElementById('modal').style.display='flex';document.getElementById('modal').setAttribute('aria-hidden','false');}
    function closeModal(){document.getElementById('modal').style.display='none';document.getElementById('modal').setAttribute('aria-hidden','true');}

    // Guided exercise runner
    let exerciseTimer = null;
    function startExercise(type){
      const area = document.getElementById('exercise-area');
      area.innerHTML = '';
      if(type==='breath'){
        area.innerHTML = '<div style="display:flex;align-items:center;gap:12px"><div class="timer" id="timer">05:00</div><div style="flex:1"><div style="font-weight:700">Box breathing — 5 minutes</div><div class="small">Inhale 4s — hold 4s — exhale 4s — hold 4s</div></div></div><div style="margin-top:12px"><button class="btn btn-primary" onclick="runTimer(300)">Start</button></div>';
      } else if(type==='journal'){
        area.innerHTML = '<div style="font-weight:700">Quick reflection</div><p class="small">Set a 5-minute timer and write without editing. Prompts: What matters most today? Where can I choose less friction?</p><div style="margin-top:12px"><button class="btn btn-primary" onclick="runTimer(300)">Start 5m timer</button></div>';
      } else if(type==='intention'){
        area.innerHTML = '<div style="font-weight:700">Intention setting</div><p class="small">Choose one guiding sentence for the next few hours. Make it simple and actionable.</p><input id="intent-input" style="width:100%;padding:8px;border-radius:8px;border:1px solid #eee;margin-top:8px" placeholder="I will..."/><div style="margin-top:12px"><button class="btn btn-primary" onclick="saveIntent()">Save & Start 2m reflection</button></div>';
      }
    }
    function runTimer(seconds){
      clearInterval(exerciseTimer);
      const timerEl = document.getElementById('timer');
      let s = seconds;
      exerciseTimer = setInterval(()=>{
        s--;
        if(timerEl) timerEl.textContent = String(Math.floor(s/60)).padStart(2,'0')+':' + String(s%60).padStart(2,'0');
        if(s<=0){clearInterval(exerciseTimer);alert('Practice complete. Notice what changed.');}
      },1000);
    }
    function saveIntent(){
      const val = document.getElementById('intent-input').value || 'My focus: small steady action.';
      closeModal();
      alert('Saved: '+val);
    }

    // Habit builder: 7-day challenge generator + printable checklist
    function generateChallenge(tag){
      const focus = document.getElementById('focus-select')?document.getElementById('focus-select').value: (tag || 'Wellness') ;
      const habits = {
        'Sleep rhythm': ['Bedtime wind-down 30m before', 'Limit screens 60m before bed', 'Consistent wake time', 'Light movement before dinner', 'Hydration earlier in day', 'Evening reflection (5m)', 'Keep room cool and dark'],
        'Morning clarity': ['Wake at consistent time', '3-min breathing', 'Write one priority', 'Hydrating ritual', 'Light stretch', 'No email first 30m', 'Walk for 10m'],
        'Stress ease': ['3 deep breaths at rising', 'Short grounding pause mid-day', 'Progressive muscle release 5m', 'Evening gratitude', 'Single task block', 'Check-in with body', 'Bedtime unwind'],
        'Movement habit': ['10-min walk', 'Short strength set', 'Stretch sequence', 'Stand every hour', 'Movement after meals', 'Balance practice', 'Gentle mobility before bed'],
        'Mindful pause': ['3 breath reset', 'Observe sensations 2m', 'Write one line', 'Mindful meal', 'Single-task 25m', 'Nature pause', 'Evening reflection']
      };
      const chosen = habits[focus] || ['5-min pause','Tiny movement','Write one sentence','Hydrate','Breath','Connect to senses','Reflect'];
      const title = (tag?tag+': ':'')+focus+' — 7‑day checklist';

      let listHtml = '<div class="printable" style="padding:18px;background:#fff;border-radius:8px">';
      listHtml += '<h2 style="margin:0 0 12px;color:#3b3b3b">'+escapeHtml(title)+'</h2>';
      listHtml += '<div style="font-size:13px;color:var(--muted);margin-bottom:10px">Tick each day when complete. Make notes on what changed.</div>';
      listHtml += '<table style="width:100%;border-collapse:collapse">';
      listHtml += '<thead><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid #eee">Habit</th>';
      for(let d=1;d<=7;d++) listHtml += '<th style="padding:6px 8px;border-bottom:1px solid #eee">Day '+d+'</th>';
      listHtml += '</tr></thead><tbody>';
      chosen.forEach((h,i)=>{
        listHtml += '<tr>';
        listHtml += '<td style="padding:8px 8px;border-bottom:1px solid #f3f1ef">'+escapeHtml(h)+'</td>';
        for(let d=1;d<=7;d++) listHtml += '<td style="padding:8px 8px;text-align:center;border-bottom:1px solid #f3f1ef"><input type="checkbox"/></td>';
        listHtml += '</tr>';
      });
      listHtml += '</tbody></table>';
      listHtml += '<div style="margin-top:12px;display:flex;gap:8px"><button class="btn btn-primary" onclick="window.print()">Print checklist</button><button class="btn btn-outline" onclick="downloadChecklist(\''+escapeHtml(title)+'\')">Download as text</button></div>';
      listHtml += '</div>';

      // show in modal-like window
      const modalRoot = document.getElementById('modal');
      openModal();
      document.getElementById('exercise-area').innerHTML = listHtml;
    }
    function downloadChecklist(title){
      let text = title + '\n\n';
      const checks = document.querySelectorAll('.printable tbody tr');
      checks.forEach(row=>{
        const habit = row.cells[0].innerText.trim();
        text += habit + '\n' ;
      });
      const blob = new Blob([text],{type:'text/plain'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = title.replace(/[^a-z0-9]/gi,'_') + '.txt';
      document.body.appendChild(a); a.click(); a.remove();
    }
    function escapeHtml(s){ return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]}); }
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f4f1;--accent:#6b4b35;--accent-2:#b78a67;--muted:#6d6d6d;--card:#fff;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#efe7dd);color:#2b2b2b}
    .container{max-width:980px;margin:28px auto;padding:20px}
    header{display:flex;align-items:center;justify-content:space-between}
    .logo{display:flex;gap:10px;align-items:center}
    .logo .mark{width:48px;height:48px;background:linear-gradient(135deg,var(--accent),var(--accent-2));border-radius:8px;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{background:var(--card);padding:18px;border-radius:12px;margin-top:16px}
    .hero h1{margin:0;color:var(--accent)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .reviews{display:flex;flex-direction:column;gap:12px}
    .review{background:var(--card);padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
    .meta{display:flex;align-items:center;gap:10px}
    .avatar{width:44px;height:44px;border-radius:8px;background:#efe0d6;display:flex;align-items:center;justify-content:center;font-weight:700;color:#7a4d34}
    .stars{color:#c47a4b}
    .carousel{position:relative}
    .carousel > button{position:absolute;top:50%;transform:translateY(-50%);background:transparent;border:0;font-size:22px;color:var(--muted);cursor:pointer}
    .left{left:-10px}
    .right{right:-10px}
    .aside-card{background:linear-gradient(180deg,#fff,rgba(255,250,247,0.9));padding:12px;border-radius:12px}
    .btn{padding:10px 12px;border-radius:10px;border:none;cursor:pointer;font-weight:700}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-outline{background:transparent;border:2px solid var(--accent-2);color:var(--accent)}
    footer{margin-top:22px;text-align:center;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div class="logo"><div class="mark">W</div><div><div style="font-weight:800">{{BUSINESS_NAME}}</div><div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div></div></div>
      <nav>
        <a href="index.html">Start</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Invest</a>
        <a href="book.html">Plan</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <h1>Real shifts from small experiments</h1>
      <p style="color:var(--muted);margin-top:6px">Client reflections on what changed when they introduced one steady practice at a time.</p>
      <div style="margin-top:12px"><button class="btn btn-primary" onclick="openModal()">Try a short exercise</button></div>
    </section>

    <div class="grid">
      <main>
        <div class="carousel">
          <button class="left" onclick="prev()">◀</button>
          <div id="slides">
            <div class="review" data-index="0">
              <div class="meta"><div class="avatar">AM</div><div><strong>A. Morgan</strong><div class="small" style="color:var(--muted)">Founder, remote team</div></div><div style="margin-left:auto" class="stars">★★★★★</div></div>
              <p style="margin-top:10px;color:var(--muted)">"We turned three scattered actions into a single reliable rhythm. The mornings feel quieter and I get more clear work done before lunch."</p>
            </div>

            <div class="review" data-index="1" style="display:none">
              <div class="meta"><div class="avatar">LJ</div><div><strong>L. Jones</strong><div class="small" style="color:var(--muted)">Designer</div></div><div style="margin-left:auto" class="stars">★★★★★</div></div>
              <p style="margin-top:10px;color:var(--muted)">"The checklist approach made tiny wins visible. Habits stuck because they felt possible. The sessions guided how to adjust, not just what to do."</p>
            </div>

            <div class="review" data-index="2" style="display:none">
              <div class="meta"><div class="avatar">CR</div><div><strong>C. Ruiz</strong><div class="small" style="color:var(--muted)">Teacher</div></div><div style="margin-left:auto" class="stars">★★★★★</div></div>
              <p style="margin-top:10px;color:var(--muted)">"My energy felt scattered. The coach helped me frame a single daily practice that changed how I arrived to each day."</p>
            </div>
          </div>
          <button class="right" onclick="next()">▶</button>
        </div>

        <section style="margin-top:16px;background:var(--card);padding:12px;border-radius:10px">
          <h3 style="margin:0;color:var(--accent)">Stories that matter</h3>
          <p style="color:var(--muted);margin-top:8px">Each testimonial maps to small, repeatable actions and the adjustments that kept them in place. No quick fixes — steady shaping.</p>
        </section>

        <section style="margin-top:12px">
          <h4 style="margin:0 0 8px;color:var(--accent)">Share your progress</h4>
          <p class="small" style="margin:0 0 8px;color:var(--muted)">If you've worked together and want to be featured, send a note with a short quote.</p>
          <button class="btn btn-outline" onclick="location.href='contact.html'">Share a story</button>
        </section>
      </main>

      <aside>
        <div class="aside-card">
          <h4 style="margin:0;color:var(--accent)">Try a mini practice</h4>
          <p class="small" style="margin-top:8px">Open a two-minute guided pause to notice shift now.</p>
          <div style="margin-top:10px;display:flex;gap:8px">
            <button class="btn btn-primary" onclick="openModal()">Open practice</button>
            <button class="btn btn-outline" onclick="generateChallenge()">7-day starter</button>
          </div>
        </div>

        <div style="margin-top:14px;background:linear-gradient(180deg,#fff,rgba(255,250,247,0.95));padding:12px;border-radius:12px">
          <h4 style="margin:0">Sources of trust</h4>
          <ul style="padding-left:18px;color:var(--muted);margin-top:8px"><li>Detailed check-ins</li><li>Shared short experiments</li><li>Adaptation, not prescription</li></ul>
        </div>
      </aside>
    </div>

    <footer>
      <div>Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • Call {{PHONE}}</div>
    </footer>
  </div>

  <!-- shared modal + habit builder scripts -->
  <div id="modal" style="display:none;position:fixed;inset:0;background:rgba(9,6,5,0.5);align-items:center;justify-content:center;padding:20px"> 
    <div style="max-width:600px;width:100%;background:#fff;padding:18px;border-radius:12px">
      <div style="display:flex;justify-content:space-between;align-items:center"><h3 style="margin:0;color:var(--accent)">Guided practice</h3><button onclick="closeModal()" style="background:transparent;border:0;font-weight:700;cursor:pointer">Close</button></div>
      <div id="modal-body" style="margin-top:12px"></div>
    </div>
  </div>

  <script>
    // Carousel
    let current = 0;
    const slides = document.querySelectorAll('.review');
    function show(i){ slides.forEach(s=>s.style.display='none'); slides[i].style.display='block'; }
    function next(){ current = (current + 1) % slides.length; show(current); }
    function prev(){ current = (current - 1 + slides.length) % slides.length; show(current); }

    // Modal + exercises (same functionality as pricing but concise variant)
    function openModal(){ document.getElementById('modal').style.display='flex'; renderModalOptions(); }
    function closeModal(){ document.getElementById('modal').style.display='none'; document.getElementById('modal-body').innerHTML=''; }
    function renderModalOptions(){ const body=document.getElementById('modal-body'); body.innerHTML = '<div style="display:flex;gap:8px"><button class="btn btn-outline" onclick="start(120,\'breath\')">Breath 2m</button><button class="btn btn-outline" onclick="start(180,\'journal\')">Journal 3m</button><button class="btn btn-outline" onclick="start(120,\'intent\')">Intend 2m</button></div><div id="mini-area" style="margin-top:12px"></div>'; }
    let miniTimer = null;
