{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plan a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f3efe9;--accent:#7b5138;--muted:#6b6b6b;--muted-2:#9b8a7f;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#efe7df);color:#2b2b2b}
    .wrap{max-width:900px;margin:28px auto;padding:20px}
    header{display:flex;align-items:center;justify-content:space-between}
    .logo{display:flex;gap:10px;align-items:center}
    .logo .mark{width:46px;height:46px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#c79b78);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .hero{background:#fff;padding:16px;border-radius:12px;margin-top:16px}
    .hero h1{margin:0;color:var(--accent)}
    .form{margin-top:16px;background:linear-gradient(180deg,#fff,rgba(255,250,248,0.95));padding:16px;border-radius:12px}
    label{display:block;margin-top:10px;font-weight:600}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #eee;margin-top:6px}
    .two-col{display:grid;grid-template-columns:1fr 1fr;gap:10px}
    .btn{padding:10px 12px;border-radius:10px;border:none;cursor:pointer;font-weight:700}
    .btn-primary{background:var(--accent);color:#fff}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    .resources{margin-top:16px;display:flex;gap:10px}
    .resource{background:#fff;padding:12px;border-radius:10px;flex:1}
    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:18px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="logo"><div class="mark">W</div><div><div style="font-weight:800">{{BUSINESS_NAME}}</div><div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div></div></div>
      <nav>
        <a href="index.html">Start</a>
        <a href="programs.html">Offerings</a>
        <a href="pricing.html">Invest</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <h1>Plan your intensive</h1>
      <p class="small">Select a structure that meets you where you are. We'll confirm details after your submission and suggest a short pre-session routine.</p>
    </section>

    <section class="form" id="booking-form">
      <h3 style="margin:0;color:var(--accent)">Book a program</h3>
      <p class="note">Choose a program, share a few details, and we'll reach out to confirm times and next steps.</p>

      <label for="program">Program</label>
      <select id="program">
        <option value="solo">Solo Alignment — single session</option>
        <option value="cycle">Guided Cycle — three sessions</option>
        <option value="foundations">Foundations — monthly support</option>
      </select>

      <div class="two-col">
        <div>
          <label for="name">Your name</label>
          <input id="name" placeholder="Full name"/>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" placeholder="you@domain.com"/>
        </div>
      </div>

      <label for="phone">Phone (optional)</label>
      <input id="phone" placeholder="{{PHONE}}"/>

      <label for="goals">Top goals / concerns</label>
      <textarea id="goals" rows="4" placeholder="Short description of what you'd like to change or stabilise"></textarea>

      <label for="availability">Preferred times</label>
      <input id="availability" placeholder="Weekday mornings, Tue/Thu afternoons, etc."/>

      <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
        <button class="btn btn-primary" onclick="submitBooking()">{{PRIMARY_CTA_LABEL}}</button>
        <button class="btn" onclick="startMiniPractice()">Try a 2‑minute practice</button>
        <div style="margin-left:auto" class="small">We reply within 48 hours.</div>
      </div>

      <div id="booking-result" style="margin-top:10px;color:var(--muted)"></div>
    </section>

    <section class="resources">
      <div class="resource">
        <h4 style="margin:0;color:var(--accent)">Prepare: 7-day starter</h4>
        <p class="small">Generate a simple 7-day checklist to begin experimenting before our first session.</p>
        <div style="margin-top:10px"><button class="btn btn-outline" onclick="generateChallenge()">Create checklist</button></div>
      </div>
      <div class="resource">
        <h4 style="margin:0;color:var(--accent)">Short practice</h4>
        <p class="small">Open a guided breathing or journaling prompt to steady attention before you book.</p>
        <div style="margin-top:10px"><button class="btn btn-primary" onclick="startMiniPractice()">Open practice</button></div>
      </div>
    </section>

    <footer>
      <div>Questions before booking? Call <strong>{{PHONE}}</strong> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    function submitBooking(){
      const data = {
        program: document.getElementById('program').value,
        name: document.getElementById('name').value,
        email: document.getElementById('email').value,
        phone: document.getElementById('phone').value,
        goals: document.getElementById('goals').value,
        availability: document.getElementById('availability').value
      };
      if(!data.name || !data.email){ document.getElementById('booking-result').textContent = 'Please share your name and email.'; return; }
      // Simulate submission
      document.getElementById('booking-result').textContent = 'Thanks, '+(data.name.split(' ')[0]||'there')+" — we'll reach out at " + data.email + ' within 48 hours to confirm.';
      // download a pre-session checklist
      setTimeout(()=>{ generateChallenge(); }, 800);
    }

    // Mini practice (modal-light)
    function startMiniPractice(){
      const w = window.open('', 'mini','width=420,height=420');
      w.document.write('<html><head><title>Practice</title><style>body{font-family:Arial,sans-serif;padding:18px;background:#fff;color:#2b2b2b}button{padding:8px 10px;border-radius:8px;border:0;background:#7b5138;color:#fff}</style></head><body>');
      w.document.write('<h3>Two-minute centering</h3>');
      w.document.write('<p style="color:#6b6b6b">Follow box breathing: 4s inhale • 4s hold • 4s exhale • 4s hold. Repeat until the timer ends.</p>');
      w.document.write('<div id="time" style="font-size:28px;font-weight:700;margin-top:8px">02:00</div>');
      w.document.write('<div style="margin-top:12px"><button id="start">Start</button></div>');
      w.document.write('<script>let t=120;let timer;document.getElementById("start").onclick=function(){timer=setInterval(()=>{t--;document.getElementById("time").textContent=("0"+Math.floor(t/60)).slice(-2)+":"+(t%60<10?"0":"")+(t%60);if(t<=0){clearInterval(timer);alert("Complete — notice one change.");window.close();}},1000);};</'+'script>');
      w.document.write('</body></html>');
      w.document.close();
    }

    // Simple checklist generator (like pricing) but downloadable as PDF via print
    function generateChallenge(){
      const focus = document.getElementById('program')? document.getElementById('program').value : 'Starter';
      const map = {
        'solo':['Morning pause','One priority','Tiny movement','Hydrate early','Single-task block','Breath reset','Evening reflection'],
        'cycle':['Micro-breath','Short walk','Priority note','Hydration','Single task','Evening gratitude','Wind-down ritual'],
        'foundations':['Consistent wake','Brief movement','Priority list','Hydration','Focused work','Reflection','Night routine']
      };
      const items = map[focus] || map['solo'];
      const popup = window.open('','_blank');
      let html = '<html><head><title>7-day checklist</title><style>body{font-family:Arial,sans-serif;padding:20px}h2{color:#7b5138}table{width:100%;border-collapse:collapse}td,th{border:1px solid #eee;padding:8px;text-align:center}th{background:#f7f3f0;color:#5d3f2e}</style></head><body>';
      html += '<h2>' + (focus.charAt(0).toUpperCase()+focus.slice(1)) + ' — 7-day checklist</h2>';
      html += '<table><thead><tr><th>Habit</th>';
      for(let i=1;i<=7;i++) html += '<th>Day '+i+'</th>';
      html += '</tr></thead><tbody>';
      items.forEach(it=>{ html += '<tr><td style="text-align:left">'+it+'</td>'; for(let d=0;d<7;d++) html += '<td></td>'; html += '</tr>'; });
      html += '</tbody></table><div style="margin-top:12px"><button onclick="window.print()">Print</button></div></body></html>';
      popup.document.write(html); popup.document.close();
    }
  </script>
</body>
</html>"} 
